"use client";

import { useState } from "react";
import { profile } from "@/lib/data";

export default function ContactForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError("");

    if (!name.trim() || !message.trim()) {
      setError("Please add your name and a short message.");
      return;
    }

    const lines = [
      `New portfolio inquiry`,
      `Name: ${name.trim()}`,
      email.trim() ? `Email: ${email.trim()}` : null,
      `Message: ${message.trim()}`,
    ].filter(Boolean);

    const text = encodeURIComponent(lines.join("\n"));
    const url = `https://wa.me/${profile.whatsapp}?text=${text}`;

    window.open(url, "_blank", "noopener,noreferrer");
    setSent(true);
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-5" noValidate>
      <Field label="Name">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Your name"
          className="field-input"
        />
      </Field>

      <Field label="Email (optional)">
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="you@example.com"
          className="field-input"
        />
      </Field>

      <Field label="Message">
        <textarea
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Tell me a little about your project or role."
          rows={4}
          className="field-input resize-none"
        />
      </Field>

      {error && (
        <p className="text-sm" style={{ color: "#d98a6a" }}>
          {error}
        </p>
      )}

      <button
        type="submit"
        className="group inline-flex items-center justify-center gap-2 self-start rounded-full px-7 py-3 text-sm font-medium transition-colors duration-300"
        style={{ background: "var(--accent)", color: "#111a15" }}
      >
        Send via WhatsApp
        <span
          aria-hidden
          className="transition-transform duration-300 group-hover:translate-x-1"
        >
          →
        </span>
      </button>

      {sent && (
        <p className="text-sm" style={{ color: "var(--sage)" }}>
          WhatsApp is opening with your message ready to send — just hit send
          there to reach me.
        </p>
      )}

      <style jsx>{`
        .field-input {
          width: 100%;
          background: var(--surface);
          border: 1px solid var(--border);
          border-radius: 10px;
          padding: 0.75rem 1rem;
          color: var(--text);
          font-size: 0.95rem;
          transition: border-color 0.25s ease, background 0.25s ease;
        }
        .field-input::placeholder {
          color: var(--text-faint);
        }
        .field-input:focus {
          border-color: var(--accent-dim);
          background: var(--surface-2);
          outline: none;
        }
      `}</style>
    </form>
  );
}

function Field({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <label className="flex flex-col gap-2 text-sm">
      <span style={{ color: "var(--text-muted)" }}>{label}</span>
      {children}
    </label>
  );
}
